import { test, expect } from '@playwright/test';

test.describe('Push Notifications', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
    await page.click(getByRole('button', { name: /allow notifications/i }));
  });

  test('should display push notification for urgent alerts', async ({ page }) => {
    await page.click(getByRole('button', { name: /send urgent alert/i }));
    const notification = await page.waitForEvent('notification');
    expect(notification.title).toBe('Urgent Alert');
    expect(notification.body).toContain('This is an urgent message');
  });

  test('should not display push notification for non-urgent alerts', async ({ page }) => {
    await page.click(getByRole('button', { name: /send non-urgent alert/i }));
    const notification = await page.waitForEvent('notification', { timeout: 5000 }).catch(() => null);
    expect(notification).toBeNull();
  });
});
